import{_ as p,c as a,o as e,a5 as r}from"./chunks/framework.DorIfSpC.js";const m=JSON.parse('{"title":"為什麼我花兩美金租 GPU，而不是花十二萬買一張","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/project/minimax-h3-third-path"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/project/minimax-h3-third-path"}],["meta",{"property":"og:title","content":"為什麼我花兩美金租 GPU，而不是花十二萬買一張 | 星智未來"}],["meta",{"name":"twitter:title","content":"為什麼我花兩美金租 GPU，而不是花十二萬買一張 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"為什麼我花兩美金租 GPU，而不是花十二萬買一張\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/project/minimax-h3-third-path\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/project/minimax-h3-third-path\\"}}"]]},"headers":[],"relativePath":"project/minimax-h3-third-path.md","filePath":"project/minimax-h3-third-path.md","lastUpdated":1786706565000}'),o={name:"project/minimax-h3-third-path.md"};function n(s,t,i,h,l,d){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="為什麼我花兩美金租-gpu-而不是花十二萬買一張" tabindex="-1">為什麼我花兩美金租 GPU，而不是花十二萬買一張 <a class="header-anchor" href="#為什麼我花兩美金租-gpu-而不是花十二萬買一張" aria-label="Permalink to &quot;為什麼我花兩美金租 GPU，而不是花十二萬買一張&quot;">​</a></h1><blockquote><p>MiniMax H3、RunPod，和地端與雲端之間的第三條路</p></blockquote><p><strong>作者</strong>：Ray <strong>日期</strong>：2026 年 8 月 13 日</p><hr><p>八月初，MiniMax 開源了 H3。</p><p>三百三十億參數，文字、圖像、影片、聲音在同一個上下文裡，一次生成十五秒帶立體聲的影片。而最讓人心動的是那句規格說明：</p><p><strong>它可以在單張 RTX 5090 上跑。</strong></p><p>你看到這句話，開了另一個分頁，查了一下 5090 的價格。</p><p>十二萬。缺貨溢價。</p><p>然後你關掉分頁，回去工作。</p><hr><p>這個動作，我猜很多人這幾天都做過一次。</p><p>模型是開源的，權重就掛在那裡，任何人都能下載。但「能下載」和「能用」之間，橫著一張顯示卡的價錢。</p><p>於是一個開放的東西，實際上只對一小群人開放。</p><hr><h2 id="兩條路-兩種卡住" tabindex="-1">兩條路，兩種卡住 <a class="header-anchor" href="#兩條路-兩種卡住" aria-label="Permalink to &quot;兩條路，兩種卡住&quot;">​</a></h2><p>想用 H3，表面上有兩個選擇。</p><p><strong>第一條是雲端 API。</strong> 便宜、方便，不用管環境，開個帳號就能生。</p><p>但你只拿得到成品。你不知道它跑了幾步，用什麼量化，多久生完一支。你不能換節點，不能改採樣器，不能接一個社群做的加速 LoRA。參數列表上有什麼，你就只能用什麼。</p><p><strong>你買到的是輸出，不是機制。</strong></p><p><strong>第二條是地端。</strong> 買一張卡，裝一套 ComfyUI，全部歸你。</p><p>但你得先付十二萬——而且是在你還不知道這東西值不值得之前。這個決定太大，大到大部分人的處理方式，就是不做決定。</p><p>一邊是看得到吃不到，一邊是門檻高到不敢跨。</p><p>大多數人就這樣停在原地。</p><hr><h2 id="第三條路-把租來的機器-變成你的地端" tabindex="-1">第三條路：把租來的機器，變成你的地端 <a class="header-anchor" href="#第三條路-把租來的機器-變成你的地端" aria-label="Permalink to &quot;第三條路：把租來的機器，變成你的地端&quot;">​</a></h2><p>還有一個選項，很少人把它當成一條「路」來講。</p><p>在 <a href="https://runpod.io?ref=s3bs0r0v" target="_blank" rel="noreferrer">RunPod</a> 上租一張 5090，一小時 0.99 美金。掛一個社群做的 ComfyUI 模板，模型自動下載，瀏覽器打開就是完整的本地介面。</p><p><strong>它不是雲端服務。它是一台你臨時擁有的地端機器。</strong></p><p>你有 root。你能開終端機，能 <code>git clone</code>，能看日誌，能裝任何節點，能把量化從 int8 換成 fp8 再換回來。整套本地端能做的事，一件都沒少。</p><p>差別只在於：這台機器不屬於你，而且你用完就把它丟掉。</p><p>我那個下午花了兩塊美金。</p><hr><h2 id="兩美金買到的不是算力-是看得見內部" tabindex="-1">兩美金買到的不是算力，是看得見內部 <a class="header-anchor" href="#兩美金買到的不是算力-是看得見內部" aria-label="Permalink to &quot;兩美金買到的不是算力，是看得見內部&quot;">​</a></h2><p>這是我原本沒想到的。</p><p>用 API 的時候，你問「這支影片生多久」，得到的是一個等待。用租來的地端環境，你在終端機打一行指令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grep &quot;Prompt executed&quot; comfyui.log</span></span></code></pre></div><p><code>Prompt executed in 72.69 seconds</code><code>Prompt executed in 292.65 seconds</code></p><p>一支五秒的片段，約 73 秒生完。十五秒的，約 5 分鐘。</p><p>長度變成三倍，時間卻是將近四倍。<strong>成本的成長比線性更陡</strong>——因為 H3 是所有幀同時去噪，幀數越多，注意力的代價漲得越快。</p><p>這個數字沒有任何 API 會告訴你。而它決定了我後面每一個規劃：一支六十秒的片要拆成幾段、預算怎麼抓、什麼時候該離開電腦。</p><p>同樣的道理，我能打開工作流的節點，一個一個看它的輸入槽。就是在那裡，我看到一個原本沒接線的槽位叫 <code>last_frame</code>。</p><p>接上之後，畫面裡的角色從「模型憑文字猜出來的樣子」，變成「跟我給的參考圖一模一樣」。</p><p><strong>這種東西不會寫在文件裡。它只會出現在你能打開來看的環境裡。</strong></p><hr><h2 id="那個下午最值錢的發現" tabindex="-1">那個下午最值錢的發現 <a class="header-anchor" href="#那個下午最值錢的發現" aria-label="Permalink to &quot;那個下午最值錢的發現&quot;">​</a></h2><p>我原本以為 H3 的十五秒是「一顆不能動的長鏡頭」。</p><p>社群的說法、我自己的筆記，都是這樣寫的：模型在長片段裡會自己亂切鏡，不可控，所以需要快速剪接的段落只能回去用舊方法一顆一顆生。</p><p>第一支十五秒跑出來，果然自己推近到特寫，又切了回去。我沒有叫它這樣做。</p><p>但接著我改了一件事。我在提示詞裡用它原生的分鏡語法，明確寫上時間：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Shot A] At 00:00.000, 桌腳低角度，空鏡。</span></span>
<span class="line"><span>[Shot B] At 00:05.000, 切到整個房間的大遠景。</span></span>
<span class="line"><span>[Shot C] At 00:10.000, 切回桌腳特寫。</span></span></code></pre></div><p>它在第五秒切了。在第十秒切了回來。</p><p>而那個「整個房間的大遠景」——<strong>不在我給的任何一張參考圖裡</strong>。它是照著文字生出來的，而且掛毯、蠟燭、抱枕、雕花桌的位置，都跟原場景對得上。</p><p>不是不可控。是要用時間戳叫它。</p><hr><h2 id="這件事改變的不是速度-是工作流的形狀" tabindex="-1">這件事改變的不是速度，是工作流的形狀 <a class="header-anchor" href="#這件事改變的不是速度-是工作流的形狀" aria-label="Permalink to &quot;這件事改變的不是速度，是工作流的形狀&quot;">​</a></h2><p>一支六十秒的影片，用五秒一顆的老方法，是十二個鏡頭。</p><p>十二次生成、十二組關鍵幀、十二次審片、十二輪修正、十一個剪接點。</p><p>而如果一次生成可以內含三次切鏡，同樣的六十秒變成<strong>四次生成</strong>。</p><p>純運算時間反而多了兩成——因為超線性成本。但要看的成品從十二支變成四支，要準備的關鍵幀砍掉一半，剪接點從十一個變成三個。</p><p><strong>運算時間你可以去吃飯，審片和修正不行。</strong></p><p>真正的成本從來不是機器在跑的那幾分鐘，是你坐在螢幕前的那幾小時。而這個發現，砍掉的正是後者。</p><p>我把這件事想通，是因為我能改提示詞、能立刻重跑、能看到日誌裡的秒數。</p><p>如果我是在 API 上按生成鈕，我大概到今天還以為十五秒是不能用的。</p><hr><h2 id="用完就丟-是特徵不是缺陷" tabindex="-1">用完就丟，是特徵不是缺陷 <a class="header-anchor" href="#用完就丟-是特徵不是缺陷" aria-label="Permalink to &quot;用完就丟，是特徵不是缺陷&quot;">​</a></h2><p>租來的環境有個顯而易見的缺點：關機之後什麼都沒了。模型要重下，節點要重裝。</p><p>我一開始以為這是代價。後來覺得，這反而是這條路最好的地方。</p><p>因為東西留不住，你會自然而然把整個建置寫成一支腳本。下載哪些檔案、放哪個資料夾、裝哪些節點、啟動參數加什麼——全部變成可執行的文字。</p><p><strong>你的工作流從「一台機器上的手工積累」，變成一份可以重現的東西。</strong></p><p>那本來就是該做的事。只是有一台自己的機器時，你永遠不會做——因為不做也能用。</p><p>而且不留東西，你就沒有被綁住。哪一區有貨就用哪一區，哪張卡便宜就開哪張卡，換一個模板只是改一行。你沒有沉沒成本，所以你可以一直換。</p><hr><h2 id="第一步的意義-是把太大的決定拆小" tabindex="-1">第一步的意義，是把太大的決定拆小 <a class="header-anchor" href="#第一步的意義-是把太大的決定拆小" aria-label="Permalink to &quot;第一步的意義，是把太大的決定拆小&quot;">​</a></h2><p>回到最開頭那個關掉的分頁。</p><p>「要不要花十二萬買一張 5090」是一個很難的決定。難的不是錢，是你在做決定的當下，<strong>手上沒有任何自己的數據</strong>。</p><p>你只有規格表、別人的評測、社群的說法。而那些東西沒辦法回答你真正想知道的事：這個模型在我的素材上、我的流程裡、我的品味底下，到底能不能用。</p><p>兩美金把這個決定拆成了兩步。</p><p>第一步很小：租一個下午，跑七支片，把該問的問題問完。第二步才是原本那個大的：現在我知道它能做什麼、不能做什麼、快多少、哪裡會壞——<strong>要不要買，這時候才是一個可以回答的問題。</strong></p><p>而且經常你會發現，第二步根本不用走。每個月租幾個下午的成本，換算起來是一千到兩千個小時的使用時數。真的用得到那麼多嗎？</p><p>如果用不到，那第一步就已經是終點了。</p><hr><h2 id="開放的東西-要有人先跨過去" tabindex="-1">開放的東西，要有人先跨過去 <a class="header-anchor" href="#開放的東西-要有人先跨過去" aria-label="Permalink to &quot;開放的東西，要有人先跨過去&quot;">​</a></h2><p>模型開源，只是把門打開。門後面還有一段路：環境、依賴、量化、節點、參數、踩過的坑。</p><p>那段路不長，但它足以讓大部分人停在門口。</p><p>我這次走完那段路，花了兩美金和一個下午。回頭看，最有價值的不是我生出來的那七支影片——它們大部分我都不會用。</p><p><strong>是我現在知道這個工具的形狀了。</strong></p><p>知道它十五秒的成本比線性陡，知道它的提示詞不能寫否定句，知道它會照著時間戳分鏡，知道它的參考圖是結構性的保證而不是許願。</p><p>這些東西沒辦法用讀的學會。你得自己開一台機器，打幾行指令，看它壞掉，然後修好。</p><p>而現在，開一台機器的門檻是兩美金。</p><p>想自己試一個下午：<a href="https://runpod.io?ref=s3bs0r0v" target="_blank" rel="noreferrer">RunPod</a>。</p><hr><p><em>本文的 RunPod 連結為推薦連結，透過它註冊我會獲得少量回饋，不影響你的價格。</em></p><p><em><a href="https://aidream.com.tw" target="_blank" rel="noreferrer">aidream.com.tw</a></em></p>`,94)])])}const g=p(o,[["render",n]]);export{m as __pageData,g as default};
